    ('4fb3a48c-f03c-52b2-8697-01ac270db9f3'::uuid, '588cc3c7-7b8a-59a6-8011-ed21c93a8ce3'::uuid, 'Quel quotidien dépasse le million d’exemplaires à la fin du XIXe siècle ?', 'mcq', '["Le Petit Journal","La Gazette","Le Figaro","L’Aurore"]'::jsonb, 0, 'La presse devient le premier média de masse de l’histoire.', 8),
    ('5eaf07b0-d2b7-573a-afc7-46c06ef07fc0'::uuid, '2d14a592-9307-5bf6-bb04-0b487053af5c'::uuid, 'Quel avantage la radio présente-t-elle sur la presse écrite ?', 'mcq', '["L’immédiateté, et l’accès de ceux que l’écrit n’atteignait pas","Une meilleure précision","Un coût de production supérieur","Une plus grande liberté légale"]'::jsonb, 0, 'Elle touche les analphabètes et crée un lien de proximité.', 1),
    ('c1ad7a4a-e1d5-53fb-a162-8ac0a727f0b4'::uuid, '2d14a592-9307-5bf6-bb04-0b487053af5c'::uuid, 'Quel discours du 18 juin 1940 illustre le rôle politique de la radio ?', 'mcq', '["L’Appel du général de Gaulle sur la BBC","Une causerie de Roosevelt","Un discours de Churchill au Parlement","Une allocution de Pétain"]'::jsonb, 0, 'Radio Londres et ses messages personnels joueront un rôle majeur.', 2),
    ('de7e02a0-c6b3-550a-a703-48ddbaa9c566'::uuid, '2d14a592-9307-5bf6-bb04-0b487053af5c'::uuid, 'Jusqu’à quand la radiodiffusion est-elle un monopole d’État en France ?', 'mcq', '["Jusqu’en 1982","Jusqu’en 1968","Jusqu’en 1974","Jusqu’en 1990"]'::jsonb, 0, 'Une autorité de régulation est alors créée, avant la privatisation de TF1 en 1987.', 3),
    ('c9fce413-e960-5ab9-8500-b979072d49bf'::uuid, '2d14a592-9307-5bf6-bb04-0b487053af5c'::uuid, 'Que révèle le débat télévisé Kennedy-Nixon de 1960 ?', 'mcq', '["Que l’apparence à l’écran peut peser plus que les arguments","Que la télévision est un média secondaire","Que le direct est impossible","Que les débats sont sans effet"]'::jsonb, 0, 'Les auditeurs radio et les téléspectateurs n’ont pas désigné le même vainqueur.', 4),
    ('26ed4e00-6df0-5b6e-a0e9-a98e0324529c'::uuid, '2d14a592-9307-5bf6-bb04-0b487053af5c'::uuid, 'Les radios libres ont été autorisées en France en 1981.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Après des années d’émissions clandestines.', 5),
    ('9b67ef18-4852-595e-911c-1031a582a660'::uuid, '2d14a592-9307-5bf6-bb04-0b487053af5c'::uuid, 'Quel conflit marque le passage à l’information en flux continu ?', 'mcq', '["La guerre du Golfe de 1991","La guerre du Vietnam","La guerre d’Algérie","La guerre des Malouines"]'::jsonb, 0, 'L’image en direct s’impose au moment où elle est le moins vérifiée.', 6),
    ('9b370ba4-fd08-52c7-b1e6-ff07c37847a8'::uuid, '2d14a592-9307-5bf6-bb04-0b487053af5c'::uuid, 'Quel effet la télévision a-t-elle eu sur la vie politique ?', 'mcq', '["Une personnalisation croissante, centrée sur la présence à l’écran","Un renforcement des partis","Une hausse de la participation électorale","Une disparition des débats"]'::jsonb, 0, 'Le format impose ses contraintes au contenu.', 7),
    ('1cd1313d-5ded-5a21-8dac-78d6f813377d'::uuid, '2d14a592-9307-5bf6-bb04-0b487053af5c'::uuid, 'Le coût élevé des médias de masse pose la question de leur propriété.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'La concentration met en jeu l’indépendance des rédactions.', 8),
    ('7d43e6c8-ade9-55bb-89dc-119b2d067386'::uuid, '6d2f712c-649d-54ac-a89b-9b904907c8f5'::uuid, 'De quel projet Internet est-il issu ?', 'mcq', '["ARPANET, un réseau de recherche militaire américain","Un projet commercial d’IBM","Un programme européen","Une initiative de l’ONU"]'::jsonb, 0, 'Réseau décentralisé, conçu pour survivre à la destruction d’un nœud.', 1),
    ('11ba661b-51ce-5c95-89ca-05f9a222c487'::uuid, '6d2f712c-649d-54ac-a89b-9b904907c8f5'::uuid, 'Qui invente le World Wide Web au CERN ?', 'mcq', '["Tim Berners-Lee","Vinton Cerf","Steve Jobs","Alan Turing"]'::jsonb, 0, 'Liens hypertextes, adresses et navigateur, entre 1989 et 1991.', 2),
    ('d175ec4c-61cd-550a-a011-8b30023fd720'::uuid, '6d2f712c-649d-54ac-a89b-9b904907c8f5'::uuid, 'Qu’est-ce qu’une bulle de filtres ?', 'mcq', '["Une exposition principalement à ce qui confirme ses convictions","Un dispositif de sécurité informatique","Un filtre publicitaire","Un moteur de recherche spécialisé"]'::jsonb, 0, 'Elle raréfie la contradiction et renforce les convictions.', 3),
    ('25baf09e-a230-5d9d-863e-a29643eb8921'::uuid, '6d2f712c-649d-54ac-a89b-9b904907c8f5'::uuid, 'Quel est le principal enjeu de l’information à l’ère d’Internet ?', 'mcq', '["Sa hiérarchisation et sa vérification, plus que son accès","Son coût d’achat","Sa vitesse de transmission","Sa longueur"]'::jsonb, 0, 'L’accès est devenu presque illimité.', 4),
    ('2e916111-3ac0-5c23-a4d7-3b80cd9f9bcb'::uuid, '6d2f712c-649d-54ac-a89b-9b904907c8f5'::uuid, 'Sur quoi repose la gratuité apparente des grandes plateformes ?', 'mcq', '["Sur la publicité, donc sur l’attention et les données","Sur des subventions publiques","Sur le mécénat","Sur les abonnements"]'::jsonb, 0, 'Le service est financé, mais pas par celui qui l’utilise.', 5),
    ('bb662983-1a1a-5bd8-a730-3e30021a30b3'::uuid, '6d2f712c-649d-54ac-a89b-9b904907c8f5'::uuid, 'Ce qui circule le plus sur les réseaux est ce qui a été le mieux vérifié.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est ce qui suscite le plus de réactions qui circule.', 6),
    ('5deabc22-eaaa-5bd5-a4f3-de6157738e01'::uuid, '6d2f712c-649d-54ac-a89b-9b904907c8f5'::uuid, 'Qu’est-ce que l’infobésité ?', 'mcq', '["Une abondance d’informations qui rend le tri plus difficile que la recherche","Un excès de publicité","Une saturation des réseaux","Un défaut de mémoire des serveurs"]'::jsonb, 0, 'Le problème s’est déplacé de la rareté vers le tri.', 7),
    ('868b0666-c98b-5e48-a61a-87040b984d33'::uuid, '6d2f712c-649d-54ac-a89b-9b904907c8f5'::uuid, 'Quelle est la véritable fracture numérique ?', 'mcq', '["La capacité à user du réseau de façon critique, au-delà de l’accès matériel","La vitesse de connexion","Le prix des appareils","La langue des contenus"]'::jsonb, 0, 'L’accès matériel ne suffit pas à réduire l’inégalité.', 8),
    ('e3f73bb7-ad56-5018-b8f6-9b92aad2a295'::uuid, '5773ea8a-001b-5d58-8070-835f392c6820'::uuid, 'De quoi le capitaine Dreyfus est-il accusé en 1894 ?', 'mcq', '["D’avoir livré des documents militaires à l’Allemagne","D’avoir déserté","D’avoir comploté contre la République","D’avoir détourné des fonds"]'::jsonb, 0, 'Il est condamné sur la foi d’une pièce mince et d’une expertise contestée.', 1),
    ('ce147de2-10d9-59b3-af4f-d890be3946a8'::uuid, '5773ea8a-001b-5d58-8070-835f392c6820'::uuid, 'Dans quel journal Zola publie-t-il « J’accuse… ! » ?', 'mcq', '["L’Aurore","Le Figaro","La Libre Parole","Le Petit Journal"]'::jsonb, 0, 'Le 13 janvier 1898, à la une, avec un titre trouvé par Clemenceau.', 2),
    ('4b1dd291-3f6e-55ab-b02c-afd1a90c6c2b'::uuid, '5773ea8a-001b-5d58-8070-835f392c6820'::uuid, 'Pourquoi Zola cherche-t-il à être poursuivi en diffamation ?', 'mcq', '["Pour obtenir un débat contradictoire public","Pour devenir célèbre","Pour éviter la prison","Par erreur juridique"]'::jsonb, 0, 'Le procès devait permettre de discuter publiquement des preuves.', 3),
    ('ac007629-27c5-5ff2-9e2a-d61a2d002d6a'::uuid, '5773ea8a-001b-5d58-8070-835f392c6820'::uuid, 'Qui découvre en 1896 que le véritable auteur du bordereau est Esterhazy ?', 'mcq', '["Le colonel Picquart","Émile Zola","Georges Clemenceau","Le capitaine Dreyfus lui-même"]'::jsonb, 0, 'L’état-major étouffe alors l’affaire.', 4),
    ('3b330a87-8685-5128-9b37-2e33bfac9f48'::uuid, '5773ea8a-001b-5d58-8070-835f392c6820'::uuid, 'Quel groupe social apparaît avec l’affaire Dreyfus ?', 'mcq', '["Les intellectuels, au sens actuel du mot","Les journalistes professionnels","Les syndicalistes","Les fonctionnaires"]'::jsonb, 0, 'Le « Manifeste des intellectuels » de janvier 1898 fixe l’usage du mot.', 5),
    ('7afc112b-6627-51d3-a98d-2f4ea0644969'::uuid, '5773ea8a-001b-5d58-8070-835f392c6820'::uuid, 'La presse a joué un rôle uniquement favorable à Dreyfus.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'La presse antidreyfusarde a déversé un antisémitisme violent et fabriqué de fausses preuves.', 6),
    ('3d938f56-7f99-52fe-9053-5be238d9afa9'::uuid, '5773ea8a-001b-5d58-8070-835f392c6820'::uuid, 'En quelle année Dreyfus est-il réhabilité ?', 'mcq', '["1906","1899","1898","1914"]'::jsonb, 0, 'Il est gracié dès 1899, mais la réhabilitation est plus tardive.', 7),
    ('e59dd058-984e-5e36-a3bc-7ffaa7ca1b88'::uuid, '5773ea8a-001b-5d58-8070-835f392c6820'::uuid, 'Que montre l’affaire sur la liberté de la presse ?', 'mcq', '["Elle a permis la calomnie et son démenti : elle est la condition de la correction de l’erreur","Qu’elle doit être limitée","Qu’elle est sans effet politique","Qu’elle garantit la vérité"]'::jsonb, 0, 'Elle n’est pas un instrument neutre, mais elle est indispensable.', 8),
    ('e7ce714e-3c7c-5a2c-ba46-63e62b6a7e14'::uuid, '07c757c6-a089-553d-8eb4-b1bc4be87856'::uuid, 'Que proclame l’article 11 de la Déclaration de 1789 ?', 'mcq', '["La libre communication des pensées et des opinions","La liberté de réunion","Le droit de vote","La liberté de culte"]'::jsonb, 0, 'En réservant la répression des abus définis par la loi.', 1),
    ('ff20f15e-659e-5358-9fcb-f4bc2a4eb110'::uuid, '07c757c6-a089-553d-8eb4-b1bc4be87856'::uuid, 'Que supprime la loi de 1881 ?', 'mcq', '["L’autorisation préalable et le cautionnement","La responsabilité des journalistes","Le droit de réponse","Le secret des sources"]'::jsonb, 0, 'Elle instaure une responsabilité a posteriori devant les tribunaux.', 2),
    ('84f5289c-c639-5163-9c9c-7988f9bcaa18'::uuid, '07c757c6-a089-553d-8eb4-b1bc4be87856'::uuid, 'Quel article de la Déclaration universelle de 1948 porte sur l’information ?', 'mcq', '["L’article 19","L’article 11","L’article 1er","L’article 10"]'::jsonb, 0, 'Chercher, recevoir et répandre les informations sans considération de frontières.', 3),
    ('8f6c1bd7-83c6-5eda-8002-cb3760e7a402'::uuid, '07c757c6-a089-553d-8eb4-b1bc4be87856'::uuid, 'Pourquoi la protection des sources est-elle essentielle au journalisme ?', 'mcq', '["Sans elle, personne n’accepte de parler à un journaliste","Elle protège les journalistes des procès","Elle garantit leur rémunération","Elle accélère la publication"]'::jsonb, 0, 'Elle est reconnue par la loi française depuis 2010.', 4),
    ('a984f14a-5d2e-5d73-b9c6-e218c718c958'::uuid, '07c757c6-a089-553d-8eb4-b1bc4be87856'::uuid, 'La liberté d’information est une liberté absolue.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Diffamation, incitation à la haine, vie privée et secret de la défense la bornent.', 5),
    ('1bdcaecc-fb3e-506e-bbb6-fecaea060ad9'::uuid, '07c757c6-a089-553d-8eb4-b1bc4be87856'::uuid, 'Qui doit décider des limites à la liberté d’information ?', 'mcq', '["Le juge, et non l’administration","Le gouvernement","Les rédactions elles-mêmes","Une commission de censure"]'::jsonb, 0, 'Ces limites sont exactement celles qu’un pouvoir invoque pour restreindre.', 6),
    ('0c0db7d4-244c-5c7a-9b56-95fa4cfc6d0e'::uuid, '07c757c6-a089-553d-8eb4-b1bc4be87856'::uuid, 'Qu’est-ce qu’une procédure-bâillon ?', 'mcq', '["Une action en justice destinée à épuiser un journaliste plutôt qu’à obtenir gain de cause","Une saisie de journaux","Une amende administrative","Une interdiction de publication"]'::jsonb, 0, 'Elle vise l’investigation par l’usure financière et morale.', 7),
    ('a9e3b14b-197d-5f0d-83a6-51b298d5795c'::uuid, '07c757c6-a089-553d-8eb4-b1bc4be87856'::uuid, 'La liberté de l’information se mesure au contenu des textes de loi.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle se mesure à ce qu’il est effectivement possible de publier.', 8),
    ('4361f4af-f336-5213-9f09-6740b8f7f18f'::uuid, 'a863886f-2e9a-5d74-9760-dadd09447449'::uuid, 'Qu’appelle-t-on le « bourrage de crâne » pendant la Grande Guerre ?', 'mcq', '["La propagande minimisant les pertes et promettant une victoire proche","La censure des lettres de soldats","Un entraînement militaire","Une méthode d’interrogatoire"]'::jsonb, 0, 'Il a nourri une défiance durable des combattants envers la presse.', 1),
    ('4954beed-a092-5a02-aa06-3386e9f5bda5'::uuid, 'a863886f-2e9a-5d74-9760-dadd09447449'::uuid, 'Quel trait caractérise la propagande totalitaire ?', 'mcq', '["La réécriture du passé, jusqu’à la retouche des photographies","La liberté de la presse locale","Le pluralisme des sources","L’absence de radio"]'::jsonb, 0, 'Contrôler le passé, c’est contrôler l’avenir, écrit Orwell.', 2),
    ('17debf05-6696-55df-9a1e-085c61f2a377'::uuid, 'a863886f-2e9a-5d74-9760-dadd09447449'::uuid, 'Quels journaux clandestins paraissent sous l’Occupation ?', 'mcq', '["Combat, Libération, Défense de la France","Le Figaro et Le Monde","La Gazette et Le Mercure","L’Aurore et Le Petit Journal"]'::jsonb, 0, 'Radio Londres diffuse en parallèle depuis l’extérieur.', 3),
    ('58baa1eb-fb70-5829-9c91-2e2f44de8747'::uuid, 'a863886f-2e9a-5d74-9760-dadd09447449'::uuid, 'Qu’était Radio-Paris sous l’Occupation ?', 'mcq', '["Une radio contrôlée par l’occupant allemand","Une radio de la Résistance","Une radio britannique","Une radio libre"]'::jsonb, 0, 'D’où la chanson « Radio-Paris ment ».', 4),
    ('7433be49-8d1d-5c4b-99f8-cc4792c38059'::uuid, 'a863886f-2e9a-5d74-9760-dadd09447449'::uuid, 'Que sont les Pentagon Papers ?', 'mcq', '["Des documents classifiés sur la guerre du Vietnam publiés en 1971","Les archives du Watergate","Un rapport de l’ONU","Un plan militaire soviétique"]'::jsonb, 0, 'Leur publication a été tentée d’être empêchée par le gouvernement.', 5),
    ('dc0a6e61-0af2-534f-819a-b03d8de1b5fc'::uuid, 'a863886f-2e9a-5d74-9760-dadd09447449'::uuid, 'Le Watergate a conduit à la démission du président Nixon.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'L’enquête du Washington Post a établi le journalisme comme contre-pouvoir.', 6),
    ('11c53538-70d6-51b3-84d4-5924f5f8e9e6'::uuid, 'a863886f-2e9a-5d74-9760-dadd09447449'::uuid, 'Comment les régimes de l’Est répondaient-ils aux radios occidentales ?', 'mcq', '["Par le brouillage systématique des émissions","En les autorisant librement","En les diffusant à la télévision","En les traduisant"]'::jsonb, 0, 'Les samizdats circulaient en parallèle, recopiés à la main.', 7),
    ('26a5e04c-5f1d-5fd9-8e25-da9046c99c1a'::uuid, 'a863886f-2e9a-5d74-9760-dadd09447449'::uuid, 'Les mécanismes de contrôle de l’information appartiennent au passé.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Censure, contrôle par la propriété, désinformation coordonnée et surveillance persistent.', 8),
    ('c8b7ae03-346f-5ed4-a45f-4103ff1f098c'::uuid, '3490b924-a381-5ec1-b763-9ad9e5ce2d9b'::uuid, 'Que distingue la doctrine des deux glaives ?', 'mcq', '["Le pouvoir spirituel de l’Église et le pouvoir temporel des princes","Le roi et l’empereur","La justice civile et la justice pénale","Le clergé régulier et le clergé séculier"]'::jsonb, 0, 'Reste à savoir lequel prime : c’est l’enjeu de toute la période.', 1),
    ('4b79ed95-d560-54bc-90e8-f83551c91c92'::uuid, '3490b924-a381-5ec1-b763-9ad9e5ce2d9b'::uuid, 'Où le roi de France est-il sacré ?', 'mcq', '["À Reims","À Paris","À Saint-Denis","À Chartres"]'::jsonb, 0, 'Oint de l’huile de la Sainte Ampoule, il devient roi par la grâce de Dieu.', 2),
    ('a2bceb13-aa51-56ca-b936-26996f0ddff3'::uuid, '3490b924-a381-5ec1-b763-9ad9e5ce2d9b'::uuid, 'Quel est l’enjeu de la querelle des Investitures ?', 'mcq', '["Savoir qui nomme les évêques, le pape ou l’empereur","Le tracé des frontières de l’Empire","La langue de la liturgie","Le montant de la dîme"]'::jsonb, 0, 'Les évêques sont aussi de grands seigneurs temporels.', 3),
    ('e03f723f-cb0f-58e6-a575-5c2d9f60f942'::uuid, '3490b924-a381-5ec1-b763-9ad9e5ce2d9b'::uuid, 'Quel texte met fin à la querelle des Investitures en 1122 ?', 'mcq', '["Le concordat de Worms","Le concordat de Bologne","La Pragmatique Sanction","L’édit de Nantes"]'::jsonb, 0, 'Investiture spirituelle par l’Église, temporelle par l’empereur.', 4),
    ('3fc20349-b4a1-5526-8da6-66d65d94c57f'::uuid, '3490b924-a381-5ec1-b763-9ad9e5ce2d9b'::uuid, 'Que donne le concordat de Bologne de 1516 au roi de France ?', 'mcq', '["La nomination des évêques","Le droit de lever la dîme","La direction des universités","Le pouvoir d’excommunier"]'::jsonb, 0, 'C’est le fondement du gallicanisme.', 5),
    ('dc88ef0a-628c-5aa4-ae22-ba6952f70c70'::uuid, '3490b924-a381-5ec1-b763-9ad9e5ce2d9b'::uuid, 'Le sacre de Charlemagne en 800 crée une dépendance à sens unique.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle est mutuelle : l’empereur tient sa légitimité du pape, le pape sa protection de l’empereur.', 6),
    ('4bae820f-4d03-5469-a159-40fc0b52bee7'::uuid, '3490b924-a381-5ec1-b763-9ad9e5ce2d9b'::uuid, 'Quel roi de France fait arrêter le pape Boniface VIII en 1303 ?', 'mcq', '["Philippe le Bel","Saint Louis","Charles VII","François Ier"]'::jsonb, 0, 'Le roi affirme être « empereur en son royaume ».', 7),
    ('db966459-b93a-5400-aaef-4ea47631bcf1'::uuid, '3490b924-a381-5ec1-b763-9ad9e5ce2d9b'::uuid, 'L’Église médiévale disposait de sa propre justice.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Elle levait aussi la dîme et encadrait enseignement, hôpitaux et assistance.', 8),
    ('fe44c64f-f6b3-5106-a474-fbc73ae9f1e8'::uuid, '6c2cf768-e581-5e5a-97bb-554bd1c6ef40'::uuid, 'Quel titre religieux le sultan ottoman portait-il ?', 'mcq', '["Celui de calife","Celui d’imam","Celui de patriarche","Celui de mufti"]'::jsonb, 0, 'Chef spirituel des musulmans sunnites, en plus du pouvoir temporel.', 1),
    ('54e34b2f-dcab-59b2-aa8b-4f2e5c60a6ac'::uuid, '6c2cf768-e581-5e5a-97bb-554bd1c6ef40'::uuid, 'En quelle année le califat est-il aboli en Turquie ?', 'mcq', '["1924","1923","1928","1937"]'::jsonb, 0, 'Un an après la proclamation de la République.', 2),
    ('0d5c7a62-9f2a-5c1a-bc90-7aca8e903153'::uuid, '6c2cf768-e581-5e5a-97bb-554bd1c6ef40'::uuid, 'De quel pays le code civil turc de 1926 est-il inspiré ?', 'mcq', '["La Suisse","La France","L’Allemagne","L’Italie"]'::jsonb, 0, 'Mariage civil, interdiction de la polygamie, égalité successorale.', 3),
    ('96d3c0b4-733c-52be-aa05-4023f3d0069e'::uuid, '6c2cf768-e581-5e5a-97bb-554bd1c6ef40'::uuid, 'Quelle réforme de 1928 constitue une rupture culturelle majeure ?', 'mcq', '["L’adoption de l’alphabet latin","L’instauration du calendrier grégorien","La réforme vestimentaire","La fermeture des confréries"]'::jsonb, 0, 'Elle coupe d’un coup l’accès aux textes anciens.', 4),
    ('a72c3312-f388-5704-8447-c9d9a13d493f'::uuid, '6c2cf768-e581-5e5a-97bb-554bd1c6ef40'::uuid, 'Le modèle kémaliste sépare-t-il l’État et la religion ?', 'mcq', '["Non, il contrôle la religion par l’État","Oui, comme en France","Non, il instaure une religion d’État","Oui, mais sans institution dédiée"]'::jsonb, 0, 'Le Diyanet nomme les imams et rédige les prêches.', 5),
    ('d1d02c25-66bd-5a47-a0f7-3bd5ddecbd4c'::uuid, '6c2cf768-e581-5e5a-97bb-554bd1c6ef40'::uuid, 'Quand la laïcité est-elle inscrite dans la Constitution turque ?', 'mcq', '["En 1937","En 1923","En 1924","En 1945"]'::jsonb, 0, 'Après plus d’une décennie de réformes.', 6),
    ('5ee70097-edf8-5f04-a606-26df2ad7c03d'::uuid, '6c2cf768-e581-5e5a-97bb-554bd1c6ef40'::uuid, 'L’armée turque est longtemps intervenue au nom de l’héritage kémaliste.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '1960, 1971, 1980 et 1997 : son pouvoir est fortement réduit après 2016.', 7),
    ('2bc9987f-f4a4-5170-96f4-83653aaea516'::uuid, '6c2cf768-e581-5e5a-97bb-554bd1c6ef40'::uuid, 'Que devient Sainte-Sophie en 2020 ?', 'mcq', '["Une mosquée","Un musée","Une église","Un site fermé au public"]'::jsonb, 0, 'Symbole du tournant contemporain sur la place du religieux.', 8),
    ('0e6c1587-f1ca-56e7-ad75-4669fa2a0672'::uuid, 'f5bd5eac-8bf8-53d1-be4b-84ba3f9e0b55'::uuid, 'Que pose la loi française de 1905 ?', 'mcq', '["La République ne reconnaît, ne salarie ni ne subventionne aucun culte","La religion est interdite dans l’espace public","L’État nomme les ministres du culte","Une religion d’État est instituée"]'::jsonb, 0, 'Elle garantit en même temps le libre exercice des cultes.', 1),
    ('fad78f06-f307-5e3c-840c-f0994ff2452f'::uuid, 'f5bd5eac-8bf8-53d1-be4b-84ba3f9e0b55'::uuid, 'Quel pays perçoit un impôt ecclésiastique collecté par l’État ?', 'mcq', '["L’Allemagne","La France","Les États-Unis","La Turquie"]'::jsonb, 0, 'C’est un régime de reconnaissance des cultes.', 2),
    ('c3886746-aa7a-5588-8cf6-aeffc486fe36'::uuid, 'f5bd5eac-8bf8-53d1-be4b-84ba3f9e0b55'::uuid, 'Quelle distinction est centrale dans la laïcité française ?', 'mcq', '["Entre l’agent public, tenu à la neutralité, et l’usager, libre de manifester ses convictions","Entre croyants et non-croyants","Entre cultes reconnus et non reconnus","Entre lieux de culte publics et privés"]'::jsonb, 0, 'La neutralité pèse sur l’État, non sur les personnes.', 3),
    ('0ddf0fee-b639-5931-93c8-1c177230cd25'::uuid, 'f5bd5eac-8bf8-53d1-be4b-84ba3f9e0b55'::uuid, 'Quel régime particulier subsiste en Alsace-Moselle ?', 'mcq', '["Le régime concordataire","La séparation stricte","La religion d’État","Le contrôle étatique du culte"]'::jsonb, 0, 'Héritage de la période où ces territoires étaient allemands.', 4),
    ('8951654d-fcaf-598f-a290-0626adec7a75'::uuid, 'f5bd5eac-8bf8-53d1-be4b-84ba3f9e0b55'::uuid, 'La liberté de changer de religion est garantie partout dans le monde.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Protégée par les textes internationaux, elle reste refusée dans plusieurs États.', 5),
    ('c1818071-a54f-51ef-a98e-f83459679c4c'::uuid, 'f5bd5eac-8bf8-53d1-be4b-84ba3f9e0b55'::uuid, 'Le Saint-Siège est un sujet de droit international.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'C’est l’un des acteurs religieux transnationaux du système international.', 6),
    ('c3118b5f-8c82-55ea-a7e1-24aa5196476a'::uuid, 'f5bd5eac-8bf8-53d1-be4b-84ba3f9e0b55'::uuid, 'Comment analyser un conflit où l’appartenance religieuse est mobilisée ?', 'mcq', '["En démêlant les enjeux de terre, de pouvoir et de mémoire derrière le marqueur religieux","En le lisant comme purement religieux","En ignorant la dimension religieuse","En le rapportant à un seul acteur"]'::jsonb, 0, 'Lire un conflit comme purement religieux est presque toujours une erreur d’analyse.', 7),
    ('27344d5a-d7d3-514a-a504-e2b8bd22f4e8'::uuid, 'f5bd5eac-8bf8-53d1-be4b-84ba3f9e0b55'::uuid, 'Quel texte international garantit la liberté de pensée, de conscience et de religion en Europe ?', 'mcq', '["L’article 9 de la Convention européenne des droits de l’homme","L’article 11 de la Déclaration de 1789","La loi de 1905","Le traité de Lisbonne"]'::jsonb, 0, 'L’article 18 de la Déclaration universelle de 1948 le fait au niveau mondial.', 8)
  ) AS v(id, quiz_id, question, kind, options, correct_index, explanation, position)
-- Le quiz doit exister : si le NOT EXISTS ci-dessus a écarté un quiz (une
-- leçon en avait déjà un), ses questions ne partent pas dans le vide.
 WHERE EXISTS (SELECT 1 FROM public.quizzes qz WHERE qz.id = v.quiz_id)
ON CONFLICT (id) DO NOTHING;

-- 5. Sonde finale ----------------------------------------------------------
DO $$
DECLARE
  n_vides integer;
  n_chap  integer;
BEGIN
  SELECT count(*) INTO n_chap FROM public.chapters c
   JOIN public.subjects s ON s.id = c.subject_id
   WHERE s.slug IN ('hggsp');
  SELECT count(*) INTO n_vides FROM public.subjects s
   WHERE s.slug IN ('hggsp')
     AND NOT EXISTS (SELECT 1 FROM public.chapters c WHERE c.subject_id = s.id);
  IF n_vides > 0 THEN
    RAISE EXCEPTION 'Migration 275 incomplète : % matiere(s) encore sans chapitre', n_vides;
  END IF;
  RAISE NOTICE 'Migration 275 OK : % chapitres sur les matieres visees.', n_chap;
END $$;
